#ifndef RISCV_SIMULATOR_INSTRUCTION_HPP
#define RISCV_SIMULATOR_INSTRUCTION_HPP

#include <utility>
#include "Common.h"
#include <string>
#include <iostream>

using Instruction = unsigned int;

struct InstructionBase {
    unsigned opcode;
    unsigned rs1;
    unsigned rs2;
    unsigned rd;
    unsigned funct3;
    unsigned funct7;
    Immediate imm;
    Instruction inst;
    enum Type { R, I, S, B, U, J } t;

    static void InvalidAccess() {
        throw std::runtime_error("Invalid field access");
    }

    InstructionBase() : opcode(0), rs1(0), rs2(0), rd(0), funct3(0), funct7(0), imm(0), inst(0), t(R) {}

    explicit InstructionBase(unsigned opcode_val) : opcode(opcode_val), rs1(0), rs2(0), rd(0), funct3(0), funct7(0), imm(0), inst(static_cast<Instruction>(-1)), t(I) {
        opcode = 0b0010011;
    }

    static InstructionBase nop() {
        return InstructionBase();
    }

    bool is_nop() const {
        return opcode == 0 && rs1 == 0 && rs2 == 0 && rd == 0 && funct3 == 0 && funct7 == 0;
    }

    static constexpr unsigned int bin_mask(int digits) {
        return (1 << digits) - 1;
    }

    static unsigned int get_digits(unsigned int n, int hi, int lo) {
        return (n >> lo) & bin_mask(hi - lo + 1);
    }

    static unsigned int expand_digit(unsigned int digit, int lo) {
        return digit ? (0xffffffff << lo) : 0;
    }

    bool is_valid(const std::string& key) const {
        if (t == R) {
            return key != "imm";
        } else if (t == I) {
            return key != "rs2" && key != "funct7";
        } else if (t == S) {
            return key != "rd" && key != "funct7";
        } else if (t == B) {
            return key != "rd" && key != "funct7";
        } else {
            return key != "rs1" && key != "rs2" && key != "funct3" && key != "funct7";
        }
    }

    void verify(const std::string& key) const {
        if (!is_valid(key)) {
            InvalidAccess();
        }
    }

    void debug() const {
        std::cout << "Instruction: 0x" << std::hex << inst << std::dec << std::endl;
        switch (opcode) {
            case 0b0110111:
                std::cout << "lui";
                break;
            case 0b0010111:
                std::cout << "auipc";
                break;
            case 0b1101111:
                std::cout << "jal";
                break;
            case 0b1100111:
                std::cout << "jalr";
                break;
            case 0b1100011:
                std::cout << "branch";
                break;
            case 0b0000011:
                std::cout << "load";
                break;
            case 0b0100011:
                std::cout << "store";
                break;
            default:
                if (opcode == 0b0010011) {
                    switch (funct3) {
                        case 0b000:
                            std::cout << "addi";
                            break;
                        case 0b010:
                            std::cout << "slti";
                            break;
                        case 0b011:
                            std::cout << "sltiu";
                            break;
                        case 0b100:
                            std::cout << "xori";
                            break;
                        case 0b110:
                            std::cout << "ori";
                            break;
                        case 0b111:
                            std::cout << "andi";
                            break;
                        default:
                            std::cout << "unknown I-type";
                    }
                } else {
                    std::cout << "unknown opcode";
                }
        }
    }

    bool has_op1() const {
        return t != U && t != J;
    }

    bool has_op2() const {
        return t == R || t == S || t == B;
    }
};

struct InstructionR : InstructionBase {
    explicit InstructionR(const Instruction &inst) {
        opcode = get_digits(inst, 6, 0);
        rd = get_digits(inst, 11, 7);
        funct3 = get_digits(inst, 14, 12);
        rs1 = get_digits(inst, 19, 15);
        rs2 = get_digits(inst, 24, 20);
        funct7 = get_digits(inst, 31, 25);
        t = R;
    }
};

struct InstructionI : InstructionBase {
    explicit InstructionI(const Instruction &inst) {
        opcode = get_digits(inst, 6, 0);
        rd = get_digits(inst, 11, 7);
        funct3 = get_digits(inst, 14, 12);
        rs1 = get_digits(inst, 19, 15);
        imm = get_digits(inst, 30, 20) | expand_digit(get_digits(inst, 31, 31), 11);
        t = I;
    }
};

struct InstructionS : InstructionBase {
    explicit InstructionS(const Instruction &inst) {
        opcode = get_digits(inst, 6, 0);
        funct3 = get_digits(inst, 14, 12);
        rs1 = get_digits(inst, 19, 15);
        rs2 = get_digits(inst, 24, 20);
        imm = get_digits(inst, 11, 7) | (get_digits(inst, 30, 25) << 5) | expand_digit(get_digits(inst, 31, 31), 11);
        t = S;
    }
};

struct InstructionB : InstructionBase {
    explicit InstructionB(const Instruction &inst) {
        opcode = get_digits(inst, 6, 0);
        funct3 = get_digits(inst, 14, 12);
        rs1 = get_digits(inst, 19, 15);
        rs2 = get_digits(inst, 24, 20);
        imm = (get_digits(inst, 11, 8) << 1) | (get_digits(inst, 30, 25) << 5) | (get_digits(inst, 7, 7) << 11) | expand_digit(get_digits(inst, 31, 31), 12);
        t = B;
    }
};

struct InstructionU : InstructionBase {
    explicit InstructionU(const Instruction &inst) {
        opcode = get_digits(inst, 6, 0);
        rd = get_digits(inst, 11, 7);
        imm = (get_digits(inst, 19, 12) << 12) | (get_digits(inst, 30, 20) << 20) | (get_digits(inst, 31, 31) << 31);
        t = U;
    }
};

struct InstructionJ : InstructionBase {
    explicit InstructionJ(const Instruction &inst) {
        opcode = get_digits(inst, 6, 0);
        rd = get_digits(inst, 11, 7);
        imm = (get_digits(inst, 30, 21) << 1) | (get_digits(inst, 20, 20) << 11) | (get_digits(inst, 19, 12) << 12) | expand_digit(get_digits(inst, 31, 31), 20);
        t = J;
    }
};

#endif // RISCV_SIMULATOR_INSTRUCTION_HPP
